import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireIdentity Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireIdentity/aireidentity-v2-20-0.md","filePath":"aireblock-releases/AireIdentity/aireidentity-v2-20-0.md","lastUpdated":1793188062000}`),a={name:`aireblock-releases/AireIdentity/aireidentity-v2-20-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireidentity-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireidentity-icon.png"> AireIdentity Release Notes</span> <a class="header-anchor" href="#aireidentity-release-notes" aria-label="Permalink to “AireIdentity Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 2.20.0<br><strong>Release Date:</strong> 4th November 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Policy Changes Recorded in the Tenant Role Audit Trail (ID-1199)</li><li>Refresh Token Usage Setting for Clients (ID-1202)</li><li>User-Scoped Access for AI Tools (ID-1210)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Client Restrictions Now Save Correctly (ID-1196)</li></ul><h4 id="🔧-tasks" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks" aria-label="Permalink to “🔧 Tasks”">​</a></h4><ul><li>Identity Platform Upgrade (ID-1207)</li></ul><h3 id="⚠️-upgrade-notes" tabindex="-1">⚠️ Upgrade Notes <a class="header-anchor" href="#⚠️-upgrade-notes" aria-label="Permalink to “⚠️ Upgrade Notes”">​</a></h3><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><ul><li><strong>Database migrations</strong> are included as part of the identity platform upgrade, adding new configuration and session tables. These are applied on deployment.</li><li><strong>Sign-in behaviour changes</strong> from the platform upgrade: <ul><li>Responses to form submissions during sign-in now redirect using HTTP 303 (See Other). Any integration that checks for a specific redirect status code should be reviewed.</li><li>Device sign-in no longer remembers previous consent decisions, so users may be asked to give consent again.</li><li>Older grants are now automatically revoked when a user&#39;s session is replaced.</li></ul></li></ul></div><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="policy-changes-recorded-in-the-tenant-role-audit-trail-id-1199" tabindex="-1">Policy Changes Recorded in the Tenant Role Audit Trail (ID-1199) <a class="header-anchor" href="#policy-changes-recorded-in-the-tenant-role-audit-trail-id-1199" aria-label="Permalink to “Policy Changes Recorded in the Tenant Role Audit Trail (ID-1199)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When a tenant role is created or updated, the AireAudit entry now lists any policies added to or removed from the role, alongside the existing added and removed permissions. This was requested by NHS Blood and Transplant.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When reviewing audit history, you can now see exactly when a role gained or lost a policy, as well as its permissions, giving you a complete picture of how access has changed over time.</p></div><h4 id="refresh-token-usage-setting-for-clients-id-1202" tabindex="-1">Refresh Token Usage Setting for Clients (ID-1202) <a class="header-anchor" href="#refresh-token-usage-setting-for-clients-id-1202" aria-label="Permalink to “Refresh Token Usage Setting for Clients (ID-1202)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A new &quot;Refresh Token Usage&quot; option on a client&#39;s Restrictions tab lets administrators choose between Reusable and One-Time Use refresh tokens, with an explanation of each. The option appears when Offline Access is enabled. New clients continue to default to Reusable, and the chosen setting is kept if Offline Access is switched off and on again.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now see and control how refresh tokens behave for each application, helping you balance security against smooth, uninterrupted sign-in for your users.</p></div><h4 id="user-scoped-access-for-ai-tools-id-1210" tabindex="-1">User-Scoped Access for AI Tools (ID-1210) <a class="header-anchor" href="#user-scoped-access-for-ai-tools-id-1210" aria-label="Permalink to “User-Scoped Access for AI Tools (ID-1210)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Tokens issued to AI clients such as Claude Desktop, when signing in to a specific AireGlu MCP server, can now carry the <code>delegate_exchange</code> scope. This allows MCP tools to exchange the user&#39;s token for one that calls other AireSuite services on that user&#39;s behalf.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>AI tools connected to AireGlu can now act as you when retrieving information, so they only return the data you are allowed to see.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="client-restrictions-now-save-correctly-id-1196" tabindex="-1">Client Restrictions Now Save Correctly (ID-1196) <a class="header-anchor" href="#client-restrictions-now-save-correctly-id-1196" aria-label="Permalink to “Client Restrictions Now Save Correctly (ID-1196)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where saving a client&#39;s Restrictions page failed with a validation error for any client that had never had a single tenant environment restriction set, including newly created clients. Unrelated changes on the same page, such as grant types, can now be saved as expected.</p></div><h3 id="🔧-tasks-1" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks-1" aria-label="Permalink to “🔧 Tasks”">​</a></h3><hr><h4 id="identity-platform-upgrade-id-1207" tabindex="-1">Identity Platform Upgrade (ID-1207) <a class="header-anchor" href="#identity-platform-upgrade-id-1207" aria-label="Permalink to “Identity Platform Upgrade (ID-1207)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The underlying identity platform (Duende IdentityServer) has been upgraded from version 7.4 to 8.0, keeping AireIdentity on a supported, up-to-date foundation. The upgrade includes database migrations and some changes to sign-in behaviour (see Upgrade Notes).</p></div>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};